from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1)
sec.top_margin = sec.bottom_margin = Inches(1)
st = doc.styles["Normal"]
st.font.name = "Times New Roman"; st.font.size = Pt(11)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
for s in ["Heading 1","Heading 2","Heading 3"]:
    h = doc.styles[s]; h.font.name = "Times New Roman"; h.font.color.rgb = RGBColor(0,0,0)
    h.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
doc.styles["Heading 1"].font.size = Pt(13)
doc.styles["Heading 2"].font.size = Pt(12)
doc.styles["Heading 3"].font.size = Pt(11)

hp = sec.header.paragraphs[0]
hp.text = "PRIVILEGED AND CONFIDENTIAL — ATTORNEY WORK PRODUCT"
hp.alignment = WD_ALIGN_PARAGRAPH.CENTER
for r in hp.runs: r.bold = True; r.font.size = Pt(9)

def add_field(par, instr):
    r = par.add_run()
    f1 = OxmlElement("w:fldChar"); f1.set(qn("w:fldCharType"), "begin")
    it = OxmlElement("w:instrText"); it.set(qn("xml:space"), "preserve"); it.text = instr
    f2 = OxmlElement("w:fldChar"); f2.set(qn("w:fldCharType"), "end")
    r._r.append(f1); r._r.append(it); r._r.append(f2)
fp = sec.footer.paragraphs[0]
fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
rr = fp.add_run("PRIVILEGED AND CONFIDENTIAL — ATTORNEY WORK PRODUCT  |  Draft for M. Shelton Review  |  Page "); rr.font.size = Pt(8)
add_field(fp, "PAGE")

def P(text="", bold=False, italic=False, size=None, align=None, space_after=6, indent=None):
    p = doc.add_paragraph()
    _runs(p, text, bold, italic, size)
    p.paragraph_format.space_after = Pt(space_after)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    if align == "j": p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if indent: p.paragraph_format.left_indent = Inches(indent)
    return p

def _runs(p, text, bold=False, italic=False, size=None):
    # **bold** markup support
    parts = text.split("**")
    for i, part in enumerate(parts):
        if not part: continue
        r = p.add_run(part)
        r.bold = bold or (i % 2 == 1)
        r.italic = italic
        if size: r.font.size = Pt(size)

def B(text, level=0):
    p = doc.add_paragraph(style="List Bullet" if level == 0 else "List Bullet 2")
    _runs(p, text)
    p.paragraph_format.space_after = Pt(3)
    return p

def N(text):
    p = doc.add_paragraph(style="List Number")
    _runs(p, text); p.paragraph_format.space_after = Pt(3)
    return p

def H(text, lvl=1):
    return doc.add_heading(text, level=lvl)

def shade(cell, color):
    tcPr = cell._tc.get_or_add_tcPr()
    sh = OxmlElement("w:shd"); sh.set(qn("w:val"), "clear"); sh.set(qn("w:color"), "auto"); sh.set(qn("w:fill"), color)
    tcPr.append(sh)

def T(headers, rows, widths=None, size=9, bold_last=False):
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = "Table Grid"
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""
        r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(size)
        shade(c, "D9D9D9")
    for ri, row in enumerate(rows):
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            p = cells[i].paragraphs[0]
            _runs(p, str(v), bold=(bold_last and ri == len(rows)-1), size=size)
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Inches(w)
    doc.add_paragraph().paragraph_format.space_after = Pt(2)
    return t

def ISSUE(num, title, desc, signif, impact, corrected, steps, priority):
    H(f"Issue {num}: {title}", 3)
    P(f"**Priority:** {priority}", space_after=3)
    P("**(a) Description of the error or omission.** " + desc[0], align="j")
    for x in desc[1:]:
        if isinstance(x, tuple) and x[0] == "table":
            T(*x[1:])
        elif x.startswith("- "): B(x[2:])
        else: P(x, align="j")
    P("**(b) Legal and practical significance.** " + signif[0], align="j")
    for x in signif[1:]:
        if x.startswith("- "): B(x[2:])
        else: P(x, align="j")
    P("**(c) Dollar impact.** " + impact, align="j")
    P("**(d) Corrected calculation.** " + corrected[0], align="j")
    for x in corrected[1:]:
        if isinstance(x, tuple) and x[0] == "table":
            T(*x[1:])
        elif x.startswith("- "): B(x[2:])
        else: P(x, align="j")
    P("**(e) Recommended next steps.**", space_after=2)
    for s in steps: B(s)
